import{_ as t,c as o,o as a,a5 as r}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"热门内容排序与定时任务","description":"","frontmatter":{"title":"热门内容排序与定时任务","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#3.4","branch":"main","level":1,"order":3.4},"headers":[],"relativePath":"posts/projects/zfeed/03-content-rpc-service/04-hot-content-ranking-and-cron-jobs.md","filePath":"posts/projects/zfeed/03-content-rpc-service/04-hot-content-ranking-and-cron-jobs.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/03-content-rpc-service/04-hot-content-ranking-and-cron-jobs.md"};function n(l,e,d,i,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="热门内容排序与定时任务" tabindex="-1">热门内容排序与定时任务 <a class="header-anchor" href="#热门内容排序与定时任务" aria-label="Permalink to &quot;热门内容排序与定时任务&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_bucket_cleanup/hot_bucket_cleanup_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_bucket_cleanup/hot_bucket_cleanup_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_cold_rebuild/hot_cold_rebuild_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_cold_rebuild/hot_cold_rebuild_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_snapshot_refresh/hot_snapshot_refresh_job.go" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_snapshot_refresh/hot_snapshot_refresh_job.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/feed_bench_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/feed_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/common/consts/redis/redis_consts.go" target="_blank" rel="noreferrer">app/rpc/count/internal/common/consts/redis/redis_consts.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_bench_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer_bench_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer_bench_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/README.md?plain=1" target="_blank" rel="noreferrer">bench/data/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/content_ids.csv" target="_blank" rel="noreferrer">bench/data/small/content_ids.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/follow_edges.csv" target="_blank" rel="noreferrer">bench/data/small/follow_edges.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/search_terms.csv" target="_blank" rel="noreferrer">bench/data/small/search_terms.csv</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/bench/data/small/tokens.json" target="_blank" rel="noreferrer">bench/data/small/tokens.json</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/hotrank/formula_bench_test.go" target="_blank" rel="noreferrer">pkg/hotrank/formula_bench_test.go</a></li></ul></details><p>热门内容排序系统负责根据用户互动（点赞、评论、收藏）和时间衰减计算内容热度。该系统保证“推荐”Feed 保持新鲜且有吸引力。它使用分片增量设计处理高并发互动更新，并通过一组分布式定时任务（由 XXL-Job 驱动）维护全局排序列表和时间点快照。</p><h2 id="热度排序公式" tabindex="-1">热度排序公式 <a class="header-anchor" href="#热度排序公式" aria-label="Permalink to &quot;热度排序公式&quot;">​</a></h2><p>排序分数使用加权互动模型，并叠加指数时间衰减因子。这样可以让新内容有机会与互动量很高的旧内容竞争。</p><h3 id="计分逻辑" tabindex="-1">计分逻辑 <a class="header-anchor" href="#计分逻辑" aria-label="Permalink to &quot;计分逻辑&quot;">​</a></h3><p>核心公式实现在 <code>pkg/hotrank/formula.go</code> 中。它通过以下组成部分计算 <code>HotScore</code>：</p><ol><li>加权互动：<code>Weighted = (Like * wLike) + (Comment * wComment) + (Favorite * wFavorite)</code>。</li><li>对数缩放：<code>Base = log1p(Weighted)</code>，避免单个爆款内容无限期主导 Feed。</li><li>时间衰减：<code>Decay = exp(-ln2 * AgeHours / HalfLifeHours)</code>。</li><li>最终分数：<code>Score = Base * Decay</code>。</li></ol><table tabindex="0"><thead><tr><th>组成项</th><th>默认权重</th><th>说明</th></tr></thead><tbody><tr><td>Like</td><td>1.0</td><td>标准正向互动。</td></tr><tr><td>Comment</td><td>3.0</td><td>评论门槛更高，表示更强参与度，因此权重更高。</td></tr><tr><td>Favorite</td><td>2.0</td><td>高意图互动。</td></tr><tr><td>Half-Life</td><td>24 小时</td><td>分数降低 50% 所需时间。</td></tr></tbody></table><p>来源：</p><ul><li><code>pkg/hotrank/formula.go:1-45</code>（公式实现）</li><li><code>app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go:180-215</code>（增量计算逻辑）</li></ul><hr><h2 id="分片增量桶" tabindex="-1">分片增量桶 <a class="header-anchor" href="#分片增量桶" aria-label="Permalink to &quot;分片增量桶&quot;">​</a></h2><p>为了避免每秒数千次互动直接写入单个全局 ZSet 造成 Redis 写瓶颈，<code>zfeed</code> 使用分片增量设计。</p><ol><li>互动捕获：互动发生时，增量事件不会直接写入全局热门 ZSet，而是被哈希到 64 个 Redis Hash 分片之一（<code>feed:hot:global:inc:{shard_id}</code>）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/common/consts/redis/redis_consts.go#L12-L14" target="_blank" rel="noreferrer">app/rpc/count/internal/common/consts/redis/redis_consts.go#12-14</a></li><li>分片结构：Hash 中每个 field 是一个 <code>content_id</code>，value 可以是原始 float（delta），也可以是包含 <code>like</code>、<code>comment</code>、<code>favorite</code> 计数的 JSON <code>ActionCounts</code> 对象。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go#L42-L47" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go#42-47</a></li><li>消费：<code>hot.fast.update</code> 任务会周期性清空这些分片，并将增量合并到全局排序中。</li></ol><p>来源：</p><ul><li><code>app/rpc/count/internal/common/consts/redis/redis_consts.go:12-14</code>（分片配置）</li><li><code>app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go:99-127</code>（分片处理循环）</li></ul><hr><h2 id="xxl-job-定时任务" tabindex="-1">XXL-Job 定时任务 <a class="header-anchor" href="#xxl-job-定时任务" aria-label="Permalink to &quot;XXL-Job 定时任务&quot;">​</a></h2><p>热门 Feed 的维护被拆分为四个独立任务，以平衡性能与一致性。</p><h3 id="_1-hot-fast-update-热路径" tabindex="-1">1. hot.fast.update（热路径） <a class="header-anchor" href="#_1-hot-fast-update-热路径" aria-label="Permalink to &quot;1. hot.fast.update（热路径）&quot;">​</a></h3><p>该任务高频运行（例如每分钟一次），用于处理近期互动。</p><ul><li>处理过程：遍历全部 64 个分片，为每个内容计算带衰减的 delta，并使用 Lua 脚本 <code>MergeHotIncScript</code> 原子地把 delta 加到全局 ZSet（<code>feed:hot:global</code>）中，同时清空分片。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go#L240-L266" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go#240-266</a></li><li>持久化：更新 MySQL <code>zfeed_content</code> 表中 Top-N 内容的 <code>hot_score</code> 列，确保数据库搜索与热门排序保持一致。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go#L217-L238" target="_blank" rel="noreferrer">app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go#217-238</a></li><li>快照：更新完成后触发新快照创建。</li></ul><h3 id="_2-hot-snapshot-refresh" tabindex="-1">2. hot.snapshot.refresh <a class="header-anchor" href="#_2-hot-snapshot-refresh" aria-label="Permalink to &quot;2. hot.snapshot.refresh&quot;">​</a></h3><p>保证推荐引擎始终有一组稳定的内容可供用户读取。</p><ul><li>目的：从全局 ZSet 创建 Top-N 内容的时间点副本。</li><li>实现：使用 <code>RebuildHotSnapshotScript</code> 将 <code>feed:hot:global</code> 复制到 <code>feed:hot:global:snap:{timestamp}</code>，并更新 <code>feed:hot:global:latest</code> 指针。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/rebuild_hot_snapshot.lua" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/rebuild_hot_snapshot.lua</a></li></ul><h3 id="_3-hot-cold-rebuild-冷路径" tabindex="-1">3. hot.cold.rebuild（冷路径） <a class="header-anchor" href="#_3-hot-cold-rebuild-冷路径" aria-label="Permalink to &quot;3. hot.cold.rebuild（冷路径）&quot;">​</a></h3><p>这是一个安全机制，用于防止漂移，并重新计算较旧内容的分数。</p><ul><li>处理过程：扫描 MySQL <code>zfeed_content</code> 表中某个时间窗口内发布的内容（例如最近 7 天），从 <code>count-rpc</code> 获取最新计数，使用完整公式重新计算分数，并覆盖全局 ZSet。</li></ul><h3 id="_4-hot-bucket-cleanup" tabindex="-1">4. hot.bucket.cleanup <a class="header-anchor" href="#_4-hot-bucket-cleanup" aria-label="Permalink to &quot;4. hot.bucket.cleanup&quot;">​</a></h3><p>对过期快照和旧分片数据做垃圾回收，避免 Redis 内存膨胀。</p><p>来源：</p><ul><li><code>app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go:21-60</code>（快速更新注册）</li><li><code>app/rpc/content/internal/cron/hot_snapshot_refresh/hot_snapshot_refresh_job.go</code>（快照刷新逻辑）</li><li><code>app/rpc/content/internal/cron/hot_cold_rebuild/hot_cold_rebuild_job.go</code>（冷重建逻辑）</li></ul><hr><h2 id="数据流-从互动到-feed" tabindex="-1">数据流：从互动到 Feed <a class="header-anchor" href="#数据流-从互动到-feed" aria-label="Permalink to &quot;数据流：从互动到 Feed&quot;">​</a></h2><p>下图将“趋势内容”这一自然语言概念连接到具体的代码实体和数据结构。</p><h3 id="排序与快照生命周期" tabindex="-1">排序与快照生命周期 <a class="header-anchor" href="#排序与快照生命周期" aria-label="Permalink to &quot;排序与快照生命周期&quot;">​</a></h3><p>来源：</p><ul><li><code>app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go:85-149</code>（任务执行流程）</li><li><code>app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua:1-106</code>（Feed 读取逻辑）</li></ul><hr><h2 id="实现细节" tabindex="-1">实现细节 <a class="header-anchor" href="#实现细节" aria-label="Permalink to &quot;实现细节&quot;">​</a></h2><h3 id="feed-读取-lua-脚本" tabindex="-1">Feed 读取 Lua 脚本 <a class="header-anchor" href="#feed-读取-lua-脚本" aria-label="Permalink to &quot;Feed 读取 Lua 脚本&quot;">​</a></h3><p><code>content-rpc</code> 服务使用 <code>query_hot_feed_zset.lua</code> 脚本提供稳定分页。该脚本会尝试使用用户 cursor 中的首选快照 ID，确保用户滚动过程中即使全局排序发生变化，也不会看到重复内容。</p><table tabindex="0"><thead><tr><th>逻辑步骤</th><th>代码实体</th></tr></thead><tbody><tr><td>解析 key</td><td>检查 <code>preferredSnapshotId</code>，再检查 <code>latestKey</code>，最后回退到 <code>globalKey</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#L23-L46" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#23-46</a></td></tr><tr><td>分数查找</td><td>使用 <code>redis.call(&#39;ZSCORE&#39;, key, cursor)</code> 找到用户上次停留的位置。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#L60-L60" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#60</a></td></tr><tr><td>分页</td><td>使用 <code>ZREVRANGEBYSCORE</code> 并做 overscan，以处理分数相同的内容。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#L74-L74" target="_blank" rel="noreferrer">app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua#74</a></td></tr></tbody></table><h3 id="分片合并-lua" tabindex="-1">分片合并 Lua <a class="header-anchor" href="#分片合并-lua" aria-label="Permalink to &quot;分片合并 Lua&quot;">​</a></h3><p><code>MergeHotIncScript</code> 确保从增量分片到全局 ZSet 的转移是原子的，避免更新丢失。</p><p>来源：</p><ul><li><code>app/rpc/content/internal/common/utils/lua/query_hot_feed_zset.lua:1-106</code>（读取脚本）</li><li><code>app/rpc/content/internal/cron/hot_fast_update/hot_fast_update_job.go:240-266</code>（合并逻辑）</li></ul>',48)])])}const _=t(c,[["render",n]]);export{b as __pageData,_ as default};
